@startuml

class Person {
  + personId : string
  + phoneNumber : string
  + keywords : string[]
}

class ResearchInstitution {
  + institutionCode : string
}

class ScientificArticle {
  + doi : string
  + title : string
}

abstract class PeerReviewedPaper {
  + citationCount : int
}

class TechnicalReport {}

class Publisher {
  + name : string
}

class Journal {
  + name : string
  + impactFactor : float
}

class Authorship {
  + position : int
}

Person "1" -- "0..*" ResearchInstitution : worksFor
Person "1..*" -- "0..*" ScientificArticle : author
(Person, ScientificArticle) .. Authorship

PeerReviewedPaper --|> ScientificArticle
TechnicalReport --|> ScientificArticle

PeerReviewedPaper "*" -- "0..*" Person : reviewedBy
TechnicalReport "*" -- "1" ResearchInstitution : publishedBy

Publisher "1" *-- "1..*" Journal
ResearchInstitution "0..*" -- "0..*" Journal : subscribesTo
PeerReviewedPaper "0..*" -- "0..1" Journal : publishedIn

@enduml

